import React, { useEffect, useId } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import { X } from 'lucide-react';

interface BottomSheetModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
  maxWidth?: string;
}

export const BottomSheetModal: React.FC<BottomSheetModalProps> = ({ 
  isOpen, 
  onClose, 
  title, 
  children,
  maxWidth = 'max-w-2xl'
}) => {
  const titleId = useId();
  const desktopMaxWidthClass = {
    'max-w-sm': 'md:max-w-sm',
    'max-w-md': 'md:max-w-md',
    'max-w-lg': 'md:max-w-lg',
    'max-w-xl': 'md:max-w-xl',
    'max-w-2xl': 'md:max-w-2xl',
    'max-w-3xl': 'md:max-w-3xl',
    'max-w-4xl': 'md:max-w-4xl',
  }[maxWidth] || 'md:max-w-2xl';

  useEffect(() => {
    if (!isOpen) return;
    const previousOverflow = document.body.style.overflow;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };
    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm"
          />
          <motion.div
            role="dialog"
            aria-modal="true"
            aria-labelledby={title ? titleId : undefined}
            initial={{ opacity: 0, y: '100%' }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className={`fixed bottom-0 left-0 right-0 z-[110] flex max-h-[calc(100dvh_-_8px_-_env(safe-area-inset-top))] w-full flex-col overflow-hidden rounded-t-[2rem] border-t border-white/10 bg-[#141414] shadow-2xl md:bottom-auto md:left-1/2 md:right-auto md:top-1/2 md:max-h-[85vh] md:-translate-x-1/2 md:-translate-y-1/2 md:rounded-3xl md:border ${desktopMaxWidthClass}`}
          >
            <div className="md:hidden w-full flex justify-center pt-3 pb-1 shrink-0">
              <div className="w-12 h-1.5 rounded-full bg-white/20" />
            </div>
            
            {title && (
              <div className="p-4 md:p-6 border-b border-white/5 flex justify-between items-center shrink-0">
                <h3 id={titleId} className="font-bold text-white text-lg md:text-xl">{title}</h3>
                <button type="button" onClick={onClose} className="grid h-11 w-11 place-items-center rounded-full text-gray-400 transition-colors hover:bg-white/10 hover:text-white" aria-label="Close">
                  <X className="w-5 h-5" />
                </button>
              </div>
            )}
            
            <div className="custom-scrollbar relative flex-1 overflow-y-auto pb-[env(safe-area-inset-bottom)] md:pb-0">
              {!title && (
                <button 
                  type="button"
                  onClick={onClose} 
                  className="absolute right-4 top-4 z-10 grid h-11 w-11 place-items-center rounded-full bg-black/50 text-gray-400 transition-colors hover:bg-black/80 hover:text-white md:hidden"
                  aria-label="Close"
                >
                  <X className="w-5 h-5" />
                </button>
              )}
              {children}
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};
